function renderDataset(){if(!data)return;setText('trainSamples',data.train.length);setText('validationSamples',data.validation.length);setText('datasetVocab',data.vocab.length-2);setText('uniqueLines',data.trainLines.length+data.validationLines.length);setText('datasetLineCount',$('datasetText').value.split(/\n/).filter(s=>s.trim()).length+' СЃС‚СЂРѕРє');const count=Math.max(1,Math.floor(($('validationLines').clientHeight||100)/39));validationPage=Math.max(0,Math.min(validationPage,Math.ceil(data.validationLines.length/count)-1));$('validationLines').innerHTML=data.validationLines.slice(validationPage*count,(validationPage+1)*count).map(words=>'<div class="validation-line">'+esc(words.join(' '))+'</div>').join('');setText('validationPage',(validationPage+1)+' / '+Math.max(1,Math.ceil(data.validationLines.length/count)));drawSplit();}
