async function importExperiment(file){if(!file)return;if(file.size>15e6)throw Error('Р¤Р°Р№Р» СЌРєСЃРїРµСЂРёРјРµРЅС‚Р° РґРѕР»Р¶РµРЅ Р±С‹С‚СЊ РјРµРЅСЊС€Рµ 15 РњР‘.');const value=JSON.parse(await file.text());if(value.version!==2||!Array.isArray(value.plan)||!Number.isInteger(value.seed)||typeof value.text!=='string'||![.1,.2,.3,.4].includes(value.ratio))throw Error('Р¤РѕСЂРјР°С‚ СЌРєСЃРїРµСЂРёРјРµРЅС‚Р° РЅРµ РїРѕРґРґРµСЂР¶РёРІР°РµС‚СЃСЏ.');const nextData=parseDataset(value.text,value.ratio,value.seed),nextModel=new Model(nextData,value.plan,value.dimension,value.seed);nextModel.restore(value.checkpoint);pause();data=nextData;model=nextModel;$('datasetText').value=value.text;$('validationRatio').value=String(value.ratio);$('seedInput').value=value.seed;$('dimension').value=String(value.dimension);$('contextInput').value=String(value.context||'').slice(0,300);$('datasetChoice').value='custom';const settings=value.settings||{};for(const [id,key]of [['learningRate','lr'],['objective','objective'],['optimizer','optimizer'],['maxSteps','maxSteps'],['patience','patience'],['monitorMetric','metric']])if(settings[key]!==undefined)$(id).value=String(settings[key]);$('goal').value=String(settings.metric==='accuracy'?(settings.goal||0)*100:settings.goal||0);$('restoreBest').checked=settings.restoreBest!==false;graph=graphFromPlan(value.plan);undoStack=[];redoStack=[];graphDirty=false;initializeSession(model.snapshot());arrangeGraph(false);notify('Р­РєСЃРїРµСЂРёРјРµРЅС‚ РѕС‚РєСЂС‹С‚. Р’РµСЃР° Рё РїР°СЂР°РјРµС‚СЂС‹ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅС‹.');}
function graphFromPlan(plan){const nodes=[{id:'input',type:'input',name:'Р’С…РѕРґ В· СЌРјР±РµРґРґРёРЅРіРё',x:80,y:80},...plan.map((n,i)=>({...JSON.parse(JSON.stringify(n)),id:'n'+i+'_'+Date.now(),x:0,y:0})),{id:'output',type:'output',name:'Р’С‹С…РѕРґ В· РІРµСЂРѕСЏС‚РЅРѕСЃС‚Рё',x:900,y:80}];return {nodes,edges:nodes.slice(1).map((n,i)=>({from:nodes[i].id,to:n.id}))};}
