function orderedGraph(){const byId=new Map(graph.nodes.map(n=>[n.id,n]));if(!byId.has('input')||!byId.has('output'))throw Error('РќСѓР¶РЅС‹ РІС…РѕРґ Рё РІС‹С…РѕРґ РіСЂР°С„Р°.');const outgoing=new Map,ingoing=new Map;for(const edge of graph.edges){if(!byId.has(edge.from)||!byId.has(edge.to)||edge.from===edge.to)throw Error('РќРµРєРѕСЂСЂРµРєС‚РЅРѕРµ СЃРѕРµРґРёРЅРµРЅРёРµ.');if(outgoing.has(edge.from)||ingoing.has(edge.to))throw Error('РћРґРёРЅ РІС…РѕРґ Рё РѕРґРёРЅ РІС‹С…РѕРґ РЅР° Р±Р»РѕРє.');outgoing.set(edge.from,edge.to);ingoing.set(edge.to,edge.from);}if(ingoing.has('input')||outgoing.has('output'))throw Error('РќРµР»СЊР·СЏ СЃРѕРµРґРёРЅСЏС‚СЊ РІС‹С…РѕРґ РіСЂР°С„Р° СЃРѕ РІС…РѕРґРѕРј.');const visited=new Set;let id='input',ordered=[];while(id){if(visited.has(id))throw Error('Р’ РіСЂР°С„Рµ РѕР±РЅР°СЂСѓР¶РµРЅ С†РёРєР».');visited.add(id);const node=byId.get(id);if(id!=='input'&&id!=='output')ordered.push(node);if(id==='output')break;id=outgoing.get(id);}if(id!=='output')throw Error('РЎРѕРµРґРёРЅРёС‚Рµ С†РµРїРѕС‡РєСѓ СЃ РІС‹С…РѕРґРѕРј.');if(visited.size!==graph.nodes.length)throw Error('Р’ РіСЂР°С„Рµ РѕСЃС‚Р°Р»РёСЃСЊ РЅРµРїРѕРґРєР»СЋС‡С‘РЅРЅС‹Рµ Р±Р»РѕРєРё.');if(ordered.length>16)throw Error('РњР°РєСЃРёРјСѓРј 16 РІС‹С‡РёСЃР»РёС‚РµР»СЊРЅС‹С… Р±Р»РѕРєРѕРІ.');const plan=ordered.map(({id,x,y,...spec})=>spec);new Model(data,plan,+$('dimension').value,+$('seedInput').value);return {plan,ordered};}
function nodeDetail(n){if(n.type==='input')return 'РЎР»РѕРІР°СЂСЊ в†’ N Г— D';if(n.type==='output')return 'РџРѕСЃР»РµРґРЅРёР№ С‚РѕРєРµРЅ в†’ СЃР»РѕРІР°СЂСЊ';if(n.type==='attention')return n.heads+' РіРѕР». В· '+(n.causal?'РєР°СѓР·Р°Р»СЊРЅРѕРµ':'РїРѕР»РЅРѕРµ')+(n.residual?' В· + РІС…РѕРґ':'');if(n.type==='ffn')return 'D в†’ '+n.expansion+'D в†’ D В· '+n.activation;if(n.type==='norm')return n.kind==='rms'?'РЎСЂРµРґРЅРµРєРІР°РґСЂР°С‚РёС‡РЅР°СЏ':'РЎСЂРµРґРЅРµРµ Рё РґРёСЃРїРµСЂСЃРёСЏ';if(n.type==='dropout')return 'Р’РµСЂРѕСЏС‚РЅРѕСЃС‚СЊ '+n.rate;if(n.type==='scale')return 'РљРѕСЌС„С„РёС†РёРµРЅС‚ '+n.factor;if(n.type==='pool')return n.kind==='mean'?'РЎСЂРµРґРЅРµРµ РїРѕ С‚РѕРєРµРЅР°Рј':'РџРѕСЃР»РµРґРЅРёР№ С‚РѕРєРµРЅ';if(n.type==='position')return 'РЎРёРЅСѓСЃС‹ Рё РєРѕСЃРёРЅСѓСЃС‹';if(n.type==='learned')return 'РћР±СѓС‡Р°РµРјР°СЏ РјР°С‚СЂРёС†Р° РїРѕР·РёС†РёР№';if(n.type==='activation')return 'РџРѕСЌР»РµРјРµРЅС‚РЅР°СЏ В· '+n.activation;return 'РћР±СѓС‡Р°РµРјРѕРµ РїСЂРµРѕР±СЂР°Р·РѕРІР°РЅРёРµ';}
function nodeSVGPath(from,to){const x1=from.x+205,y1=from.y+40,x2=to.x,y2=to.y+40,bend=Math.max(45,Math.abs(x2-x1)*.45);return `M ${x1} ${y1} C ${x1+bend} ${y1}, ${x2-bend} ${y2}, ${x2} ${y2}`;}
