function fitGraph(){if(!graph||!$('scratch').clientWidth)return;const minX=Math.min(...graph.nodes.map(n=>n.x)),minY=Math.min(...graph.nodes.map(n=>n.y)),maxX=Math.max(...graph.nodes.map(n=>n.x+205)),maxY=Math.max(...graph.nodes.map(n=>n.y+90)),w=$('scratch').clientWidth,h=$('scratch').clientHeight;graphScale=Math.max(.25,Math.min(1.2,(w-75)/Math.max(250,maxX-minX),(h-100)/Math.max(140,maxY-minY)));graphOffset={x:(w-(maxX-minX)*graphScale)/2-minX*graphScale,y:(h-(maxY-minY)*graphScale)/2-minY*graphScale-8};transformWorld();}
