function paletteItems(){const query=$('blockSearch').value.trim().toLocaleLowerCase('ru'),category=$('blockCategory').value;return CATALOG.map((c,i)=>({...c,index:i})).filter(c=>(category==='all'||c.group===category)&&(!query||(c.name+' '+c.hint).toLocaleLowerCase('ru').includes(query)));}
