function nodeOutShape(n){return n&&n.type==='pool'?'1Г—D':'NГ—D';}
function nodeShape(n){if(!n)return '';if(n.type==='input')return 'СЃР»РѕРІР°СЂСЊ V в†’ NГ—D';if(n.type==='output')return '1Г—D в†’ V';if(n.type==='pool')return 'NГ—D в†’ 1Г—D';return 'NГ—D в†’ NГ—D';}
let ctxMenu=null,drawerFocus=null,drawerMatrices=[];
function closeMenu(){if(ctxMenu){ctxMenu.el.remove();ctxMenu=null;}}
function openMenu(items,x,y,title){closeMenu();const el=document.createElement('div');el.className='ctx-menu';el.innerHTML=(title?'<div class="ctx-title">'+esc(title)+'</div>':'')+items.map((item,i)=>item.separator?'<div class="ctx-sep"></div>':'<button class="ctx-item'+(item.danger?' danger':'')+(item.disabled?' disabled':'')+'" data-menu="'+i+'">'+(item.icon?'<span class="ctx-icon">'+esc(item.icon)+'</span>':'')+'<span class="ctx-stack">'+esc(item.label)+(item.note?'<small>'+esc(item.note)+'</small>':'')+'</span>'+(item.sub?'<span class="ctx-arrow">вЂє</span>':'')+'</button>').join('');document.body.appendChild(el);const r=el.getBoundingClientRect();el.style.left=Math.round(Math.max(6,Math.min(x,innerWidth-r.width-8)))+'px';el.style.top=Math.round(Math.max(6,Math.min(y,innerHeight-r.height-8)))+'px';el.addEventListener('click',event=>{const button=event.target.closest('[data-menu]');if(!button)return;const item=items[+button.dataset.menu];if(item.disabled||item.separator)return;closeMenu();if(item.sub){const parent=items;openMenu([{label:'в†ђ РќР°Р·Р°Рґ',icon:'в†©',action:()=>openMenu(parent,x,y,title)},...item.sub()],x,y,item.label);}else item.action&&item.action();});ctxMenu={el};}
function catalogItems(action){return CATALOG.map((item,i)=>({label:item.name,note:item.hint+' В· '+item.group,action:()=>action(i)}));}
function nodeName(id){const n=graph.nodes.find(n=>n.id===id);return n?n.name:id;}
function duplicateNode(node){if(graph.nodes.length>=18)throw Error('РќР° С‡РµСЂРЅРѕРІРёРєРµ РЅРµ Р±РѕР»РµРµ 16 РІС‹С‡РёСЃР»РёС‚РµР»СЊРЅС‹С… Р±Р»РѕРєРѕРІ.');pushUndo();const copy={...JSON.parse(JSON.stringify(node)),id:'n'+Date.now()+'_'+Math.random().toString(36).slice(2,6),x:Math.max(0,Math.min(2700,node.x+40)),y:Math.max(0,Math.min(1800,node.y+55))};graph.nodes.push(copy);const edge=graph.edges.find(e=>e.from===node.id);if(edge){const next=edge.to;edge.to=copy.id;graph.edges.push({from:copy.id,to:next});}selectedNode=copy.id;graphChanged();}
function insertBetween(index,edge){if(graph.nodes.length>=18)throw Error('РќР° С‡РµСЂРЅРѕРІРёРєРµ РЅРµ Р±РѕР»РµРµ 16 РІС‹С‡РёСЃР»РёС‚РµР»СЊРЅС‹С… Р±Р»РѕРєРѕРІ.');const item=CATALOG[index];if(!item)return;const from=graph.nodes.find(n=>n.id===edge.from),to=graph.nodes.find(n=>n.id===edge.to);if(!from||!to)return;pushUndo();const node={...JSON.parse(JSON.stringify(item.defaults)),type:item.type,name:item.name,id:'n'+Date.now()+'_'+Math.random().toString(36).slice(2,6),x:Math.max(0,Math.min(2700,Math.round((from.x+to.x)/2-102))),y:Math.max(0,Math.min(1800,Math.round((from.y+to.y)/2)))};graph.nodes.push(node);graph.edges=graph.edges.filter(e=>e!==edge);graph.edges.push({from:edge.from,to:node.id},{from:node.id,to:edge.to});selectedNode=node.id;graphChanged();}
function insertAfter(index,nodeId){const edge=graph.edges.find(e=>e.from===nodeId);return edge?insertBetween(index,edge):addBlock(index);}
